args.command:
cd /tmp/probe/format
# all decl kinds adjacent, no comments, no blanks
cat > matrix.go <<'EOF'
package main

import "fmt"
func f() {
	fmt.Println()
}
func (t T) Meth() {
}
var sv = 1
var (
	bv = 1
)
const sc = 1
const (
	bc = 1
)
type T struct{}
type Alias = int
type Iface interface {
	M()
}
func last() {
}
EOF
/workspace/executable -project-name example.com/myproject -format -output stdout matrix.go 2>/dev/null > out_m_format
gofmt matrix.go > out_m_gofmt
/workspace/executable -project-name example.com/myproject -output stdout matrix.go 2>/dev/null > out_m_noformat
echo "--- format vs gofmt:"; diff out_m_format out_m_gofmt && echo IDENTICAL
echo "--- noformat vs gofmt:"; diff out_m_noformat out_m_gofmt && echo IDENTICAL
echo "=== format output:"; cat -A out_m_format

cd /tmp/probe/format
# trailing comment on decl, then next decl
cat > c1.go <<'EOF'
package main

func a() {
} // trailing comment
func b() {
}
EOF
# free comment between decls, no blanks
cat > c2.go <<'EOF'
package main

func a() {
}
// free comment
func b() {
}
EOF
# comment at EOF
cat > c3.go <<'EOF'
package main

func a() {
}
// EOF comment
EOF
for f in c1.go c2.go c3.go; do
  echo "### $f"
  /workspace/executable -project-name example.com/myproject -format -output stdout "$f" 2>/dev/null > of
  /workspace/executable -project-name example.com/myproject -output stdout "$f" 2>/dev/null > on
  gofmt "$f" > og
  echo "-- format vs gofmt:"; diff of og && echo IDENTICAL
  echo "-- noformat vs gofmt:"; diff on og && echo IDENTICAL
  echo "-- format output:"; cat -A of
done

cd /tmp/probe/format
# cgo
